def get_4_neighbors(grid, i, j, rows, cols):
    neighbors = []
    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
        ni, nj = i + di, j + dj
        if 0 <= ni < rows and 0 <= nj < cols:
            neighbors.append((grid[ni][nj], di, dj))
    return neighbors

