# Try: for each 4, fill with the average (rounded) of existing neighbors first, then repeatedly
# This is basically morphological dilation

def dilate(grid, background=4):
    result = [[0]*len(grid[0]) for _ in range(len(grid))]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == background:
                neighbors = set()
                for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                        neighbors.add(grid[ni][nj])
                non_bg_neighbors = [v for v in neighbors if v != background]
                if non_bg_neighbors:
                    result[i][j] = max(set(non_bg_neighbors))  # Take max non-bg
                else:
                    result[i][j] = background
            else:
                result[i][j] = grid[i][j]
    return result

